O=pathlib.Path(__file__).resolve().parent;R=O.parents[3];os.chdir(R);start=time.monotonic();sha=lambda p:hashlib.sha256(pathlib.Path(p).read_bytes()).hexdigest();unit=sys.argv[1];expect={'t061':'6d32f467fc6960f3c9c61feb611bdbb88ec2498f878ed48ab38dc4ce7e2e4a12','t036':'63bf877e96acbab78ab3003b4471ae117486d47a70563b626284ab5910a5cc87'};Q=R/('qa/coordination/resume-20261015/'+unit+'-current-dependencies/broker-request.json');assert sha(Q)==expect[unit];q=json.loads(Q.read_text());pins={str(R/p):v for p,v in q['pins'].items()};mismatch=[p for p,v in pins.items() if not pathlib.Path(p).is_file() or sha(p)!=v];assert not mismatch,'source pin drift: '+str(mismatch)
